  private val NAME_UTF8: ByteArray
  private val NAME_OFFSETS: IntArray
  private val CODE_POINTS: IntArray

  init {
    val packed = Base64.decode(PACKED_B64)
    var o = 0
    fun readInt(): Int {
      val v =
        ((packed[o].toInt() and 0xFF) shl 24) or
          ((packed[o + 1].toInt() and 0xFF) shl 16) or
          ((packed[o + 2].toInt() and 0xFF) shl 8) or
          (packed[o + 3].toInt() and 0xFF)
      o += 4
      return v
    }
    val count = readInt()
    val offsets = IntArray(count + 1)
    for (i in 0..count) {
      offsets[i] = readInt()
    }
    val cps = IntArray(count)
    for (i in 0 until count) {
      cps[i] = readInt()
    }
    val utf8Len = readInt()
    NAME_UTF8 = packed.copyOfRange(o, o + utf8Len)
    NAME_OFFSETS = offsets
    CODE_POINTS = cps
  }

  fun codePointOf(name: String): Int {
    val key = normalize(name)
    algorithmicCodePoint(key)?.let { return it }
    val utf8 = key.encodeToByteArray()
    var lo = 0
    var hi = CODE_POINTS.size - 1
    while (lo <= hi) {
      val mid = (lo + hi) ushr 1
      val cmp = compareName(utf8, mid)
      when {
        cmp < 0 -> hi = mid - 1
        cmp > 0 -> lo = mid + 1
        else -> return CODE_POINTS[mid]
      }
    }
    throw IllegalArgumentException("unknown Unicode character name: $name")
  }

  private fun algorithmicCodePoint(name: String): Int? {
    hexSuffix(name, "CJK UNIFIED IDEOGRAPH-")?.let { return it }
    hexSuffix(name, "CJK COMPATIBILITY IDEOGRAPH-")?.let { return it }
    hexSuffix(name, "TANGUT IDEOGRAPH-")?.let { return it }
    hexSuffix(name, "KHITAN SMALL SCRIPT CHARACTER-")?.let { return it }
    hexSuffix(name, "NUSHU CHARACTER-")?.let { return it }
    if (name.startsWith("HANGUL SYLLABLE ")) {
      return hangulSyllable(name.substring("HANGUL SYLLABLE ".length))
    }
    return null
  }

  private fun hexSuffix(name: String, prefix: String): Int? {
    if (!name.startsWith(prefix)) return null
    val hex = name.substring(prefix.length)
    if (hex.isEmpty()) return null
    return hex.toIntOrNull(16)
  }

  private val HANGUL_L =
    arrayOf(
      "G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "",
      "J", "JJ", "C", "K", "T", "P", "H",
    )

  private val HANGUL_V =
    arrayOf(
      "A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE",
      "OE", "YO", "U", "WEO", "WE", "WI", "YU", "EU", "YI", "I",
    )

  private val HANGUL_T =
    arrayOf(
      "", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB",
      "LS", "LT", "LP", "LH", "M", "B", "BS", "S", "SS", "NG", "J",
      "C", "K", "T", "P", "H",
    )

  private fun hangulSyllable(rest: String): Int? {
    val lOrder = HANGUL_L.indices.sortedByDescending { HANGUL_L[it].length }
    val vOrder = HANGUL_V.indices.sortedByDescending { HANGUL_V[it].length }
    for (l in lOrder) {
      val lead = HANGUL_L[l]
      if (!rest.startsWith(lead)) continue
      val afterL = rest.substring(lead.length)
      for (v in vOrder) {
        val vowel = HANGUL_V[v]
        if (!afterL.startsWith(vowel)) continue
        val afterV = afterL.substring(vowel.length)
        for (t in HANGUL_T.indices) {
          if (afterV == HANGUL_T[t]) {
            return 0xAC00 + (l * 21 + v) * 28 + t
          }
        }
      }
    }
    return null
  }

  private fun compareName(key: ByteArray, index: Int): Int {
    val start = NAME_OFFSETS[index]
    val end = NAME_OFFSETS[index + 1]
    val len = end - start
    val n = minOf(key.size, len)
    for (i in 0 until n) {
      val d = (key[i].toInt() and 0xFF) - (NAME_UTF8[start + i].toInt() and 0xFF)
      if (d != 0) return d
    }
    return key.size - len
  }

  private fun normalize(name: String): String {
    val trimmed = name.trim()
    if (trimmed.indexOf(' ') < 0 && trimmed.indexOf('\t') < 0) {
      return trimmed.uppercase()
    }
    val sb = StringBuilder(trimmed.length)
    var pendingSpace = false
    for (ch in trimmed) {
      if (ch == ' ' || ch == '\t') {
        pendingSpace = sb.isNotEmpty()
        continue
      }
      if (pendingSpace) {
        sb.append(' ')
        pendingSpace = false
      }
      sb.append(ch.uppercaseChar())
    }
    return sb.toString()
  }
}
